// TestVerifyNoTargetsReturns503 is a TEMPORARY verification test.
func TestVerifyNoTargetsReturns503(t *testing.T) {
	u, _ := url.Parse("http://127.0.0.1:1")

	rr := NewRoundRobinBalancer([]*ProxyTarget{{Name: "t", URL: u}})
	rr.RemoveTarget("t")

	balancers := map[string]ProxyBalancer{
		"random-nil":         NewRandomBalancer(nil),
		"roundrobin-nil":     NewRoundRobinBalancer(nil),
		"roundrobin-removed": rr,
	}

	for name, b := range balancers {
		e := echo.New()
		e.Use(Proxy(b))
		req := httptest.NewRequest(http.MethodGet, "/", nil)
		rec := httptest.NewRecorder()
		e.ServeHTTP(rec, req)
		if rec.Code != http.StatusServiceUnavailable {
			t.Errorf("%s: expected status %d, got %d", name, http.StatusServiceUnavailable, rec.Code)
		} else {
			t.Logf("%s: got status %d", name, rec.Code)
		}
	}
}

