// check that each registered route is reachable by a concrete path derived from it
func TestZZRegisteredRoutesReachable(t *testing.T) {
	for si, set := range zzRouteSets {
		e := New()
		for _, p := range set {
			e.router.Add(http.MethodGet, p, func(c Context) error { return nil })
		}
		for _, p := range set {
			reqPath := zzConcrete(p)
			h, c, pv := zzFind(e, http.MethodGet, reqPath)
			if pv != nil {
				t.Errorf("PANIC set=%d %v route=%q req=%q: %v", si, set, p, reqPath, pv)
				continue
			}
			_ = h
			got := c.Path()
			if got == "" {
				t.Errorf("set=%d %v route=%q req=%q -> 404 (path=%q)", si, set, p, reqPath, got)
				continue
			}
			if got != p {
				t.Logf("set=%d %v route=%q req=%q -> matched %q (params=%v)", si, set, p, reqPath, got, c.ParamNames())
			}
			// params must be filled
			for _, name := range c.ParamNames() {
				if v := c.Param(name); v == "" && name != "*" {
					t.Errorf("set=%d %v route=%q req=%q matched %q empty param %q", si, set, p, reqPath, got, name)
				}
			}
		}
	}
}

func zzConcrete(route string) string {
	parts := strings.Split(route, "/")
	for i, p := range parts {
		if strings.HasPrefix(p, ":") {
			parts[i] = "v" + fmt.Sprint(i)
		} else if strings.Contains(p, "*") {
			parts[i] = strings.Replace(p, "*", "wild", 1)
		}
	}
	out := strings.Join(parts, "/")
	if out == "" {
		out = "/"
	}
	return out
}
